/// DryRun execution completes without crash.
/// 
/// This is the minimal smoke test: build the DAG, run it in DryRun
/// with explicit boundary mocks, and verify it completes successfully.
#[test]
fn test_dryrun_completion() {
    if !guard_test("test_dryrun_completion", TestClass::Integration, FermiCost::L, &["http"], &[]) {
    return;
};
    let dag = gunbc_resolve::builder::build_dsl_graph_dag("gunbc/auth/patterns.dag", gunbc_resolve::BuildOpts::default()).expect("graph should build");
    let log = execute_dag(&dag, ExecuteConfig { mode: ExecutionMode::DryRun(mock_spec().to_boundary_mocks()), ..Default::default() }).expect("DryRun execution should complete without crash");
    assert!(!log.entries.is_empty(), "execution should produce log entries");
}

